var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||s.path!="Assets/Scenes/CM_CrookedMortar_Production02.unity")throw new System.Exception("Wrong scene");var kit="Assets/BlightBloom/Art/Architecture/CrookedMortar/";var source=AssetDatabase.LoadAssetAtPath<GameObject>(kit+"EntranceBay01/Prefabs/CM_EntranceBay01_Painted_v01.prefab");var parts=source.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name.StartsWith("02_Stone")).ToArray();if(parts.SelectMany(r=>r.sharedMaterials).Distinct().Count()!=1)throw new System.Exception("Expected shared source stone atlas");var mesh=new Mesh{name="CM02_FittedEntranceStoneSurround"};mesh.CombineMeshes(parts.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=r.transform.localToWorldMatrix}).ToArray(),true,true);mesh.vertices=mesh.vertices.Select(v=>new Vector3(v.x*1.1f,(v.y-.22f)*(2.7f/2.38f),v.z-.175f)).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,kit+"Production02/Models/CM02_FittedEntranceStoneSurround.asset");var entry=GameObject.Find("12 Entrance portal sign lanterns and herbs");foreach(var r in entry.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name.StartsWith("Entry surround ")).ToArray())UnityEngine.Object.DestroyImmediate(r.gameObject);var g=new GameObject("Fitted EntryBay01 stone surround - seated to floor and outboard hinge");g.transform.SetParent(entry.transform,false);g.transform.SetPositionAndRotation(new Vector3(3.7f,.2f,-.2f),Quaternion.Euler(0,180,0));g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=parts[0].sharedMaterial;
PrefabUtility.SaveAsPrefabAsset(entry,kit+"Production02/Prefabs/CM02_EntranceInstallation.prefab");UnityEditor.SceneManagement.EditorSceneManager.SaveScene(s);return new{min=g.GetComponent<Renderer>().bounds.min.ToString(),max=g.GetComponent<Renderer>().bounds.max.ToString(),material=parts[0].sharedMaterial.name};
